{
  "avaliacoes": [
    {
      "id": "E091d957481edf3a5",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Nos estágios iniciais de um incêndio, a resposta envolve parada da unidade, isolamento dos fluxos de inflamáveis e acionamento dos sistemas ativos de combate a incêndio; nesse intervalo, a ausência de proteção passiva em suportes de tubulações, equipamentos e elementos estruturais pode levar à perda de resistência ao fogo, colapso e escalonamento do acidente.",
          "trechos": [
            "E091d957481edf3a5:0:699"
          ],
          "condicoes": [
            "Aplicável aos estágios iniciais do incêndio",
            "Considera o período em que a equipe e os sistemas estão voltados à parada, isolamento e combate ativo"
          ],
          "limites": [
            "O trecho trata da interface entre resposta ativa e PPCI, não detalha sequências operacionais completas de combate",
            "Não fornece critérios de dimensionamento, tempo de resposta ou desempenho dos sistemas ativos"
          ]
        },
        {
          "proposicao": "A fonte associa a seleção e aplicação típica de PPCI a uma avaliação específica de cada instalação, considerando estudos de propagação de incêndio e explosão e a estratégia de resposta a emergência adotada.",
          "trechos": [
            "E091d957481edf3a5:699:1399"
          ],
          "condicoes": [
            "Aplicável a regiões críticas de instalações marítimas de produção",
            "Dependente dos estudos de propagação e da estratégia de resposta definida para a instalação"
          ],
          "limites": [
            "As aplicações típicas são apresentadas como indicações baseadas em experiência, não como regra universal",
            "O trecho não lista todas as regiões críticas nem critérios fechados de seleção"
          ]
        },
        {
          "proposicao": "A ausência, degradação ou instalação fora de especificação da PPCI é relacionada ao escalonamento do cenário acidental e à redução do tempo disponível para evacuação segura e controle da emergência.",
          "trechos": [
            "E091d957481edf3a5:1399:2092"
          ],
          "condicoes": [
            "Aplicável quando a PPCI compõe elemento crítico de segurança operacional",
            "Vinculado ao contexto de incêndio com potencial de falha de elementos críticos"
          ],
          "limites": [
            "O trecho não quantifica a redução do tempo disponível nem estabelece limiares de aceitabilidade",
            "Não substitui comprovação específica por análise de risco da instalação"
          ]
        }
      ]
    },
    {
      "id": "Ef16ea48178974452",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Na fiscalização do FPSO Espírito Santo, a ANP registrou reparos temporários em tubulações que não seguiram normas internacionais, concluindo que a contenção dos fluidos não estava garantida, o que conecta integridade mecânica da rede e capacidade de resposta segura em emergência.",
          "trechos": [
            "Ef16ea48178974452:0:692"
          ],
          "condicoes": [
            "Constatação feita no contexto de fiscalização que levou à interdição da unidade",
            "Aplicável ao caso específico do FPSO Espírito Santo"
          ],
          "limites": [
            "O trecho não identifica todas as linhas afetadas nem diferencia por subsistema",
            "Não apresenta critérios de reparo aceitável nem desempenho residual"
          ]
        },
        {
          "proposicao": "A existência de recomendações de inspeção vencidas e sem monitoramento em sistemas de fluido perigoso e na rede de água de combate a incêndio foi tratada como desvio crítico, relacionando monitoramento de integridade à disponibilidade operacional da resposta a incêndio.",
          "trechos": [
            "Ef16ea48178974452:692:1386"
          ],
          "condicoes": [
            "Constatação no FPSO Espírito Santo durante ação de fiscalização",
            "Aplicável ao conjunto de sistemas citados no trecho"
          ],
          "limites": [
            "O trecho não informa periodicidades, métodos de inspeção ou quantidade de recomendações vencidas",
            "Não descreve o impacto hidráulico específico sobre a rede de incêndio"
          ]
        },
        {
          "proposicao": "A fiscalização apontou que o sistema de drenagem não tinha capacidade para drenar a vazão do dilúvio, com agravamento por transbordamento de óleo para o main deck e para o mar, evidenciando a interface operacional entre drenagem e uso de água de combate a incêndio.",
          "trechos": [
            "Ef16ea48178974452:692:1386"
          ],
          "condicoes": [
            "Achado inserido no cenário fiscalizado do FPSO Espírito Santo",
            "Aplicável ao funcionamento do dilúvio e ao escoamento associado"
          ],
          "limites": [
            "O trecho não fornece a vazão de projeto do dilúvio nem critérios de aceitação da drenagem",
            "Não permite generalizar a falha para outras instalações"
          ]
        }
      ]
    },
    {
      "id": "Ee8bb0b543d49f847",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Em auditorias de 2015, a ANP apontou como motivo recorrente de interdição o gerenciamento inadequado da integridade de sistemas e equipamentos críticos, incluindo plano de manutenção, teste e inspeção não cumprido conforme recomendação do fabricante.",
          "trechos": [
            "Ee8bb0b543d49f847:695:1385"
          ],
          "condicoes": [
            "Constatação em auditorias de instalações marítimas de produção e perfuração",
            "Aplicável ao contexto descrito no relatório anual de 2015"
          ],
          "limites": [
            "O trecho não detalha quais equipamentos críticos de combate a incêndio estavam sujeitos ao desvio em cada unidade",
            "Mistura exemplos de produção e perfuração, exigindo cautela para uso específico em FPSO"
          ]
        },
        {
          "proposicao": "Foram registrados casos de sistema de combate a incêndio inoperante e de falta de peças ou equipamentos sobressalentes para sistemas críticos, inclusive ausência de sobressalente para manter a disponibilidade de canhões de incêndio em instalação de produção.",
          "trechos": [
            "Ee8bb0b543d49f847:695:1385",
            "Ee8bb0b543d49f847:1385:2079"
          ],
          "condicoes": [
            "Constatações oriundas das auditorias mencionadas no relatório",
            "No caso dos canhões de incêndio, o exemplo refere-se a instalação de produção"
          ],
          "limites": [
            "O trecho não informa quantidade de equipamentos indisponíveis nem critérios mínimos de estoque",
            "Não distingue se a indisponibilidade comprometia toda a estratégia de combate ou apenas parte dela"
          ]
        },
        {
          "proposicao": "O relatório relaciona falha no planejamento da resposta a emergência à ausência, nos PREs, de definição da composição mínima das estruturas organizacionais de resposta.",
          "trechos": [
            "Ee8bb0b543d49f847:2079:2354"
          ],
          "condicoes": [
            "Constatação específica para instalações de produção nas auditorias de 2015",
            "Aplicável ao conteúdo dos Planos de Resposta a Emergência avaliados"
          ],
          "limites": [
            "O trecho não define qual composição seria suficiente nem apresenta método de dimensionamento",
            "Não descreve treinamento, turnos ou disponibilidade temporal das equipes"
          ]
        }
      ]
    },
    {
      "id": "Ec300a4f6074de672",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte descreve água nebulizada como aplicada, segundo referências citadas, a incêndios envolvendo jato de gás, líquidos combustíveis e inflamáveis, sólidos perigosos e alguns equipamentos elétricos e eletrônicos, apresentando variedade de cenários possíveis de uso do agente.",
          "trechos": [
            "Ec300a4f6074de672:698:1393"
          ],
          "condicoes": [
            "Atribuição feita pela fonte a referências como NFPA",
            "Apresentada em contexto acadêmico e de compilação bibliográfica"
          ],
          "limites": [
            "Fonte sem fronteiras documentais claras e com marcadores numéricos apagados",
            "A enumeração de aplicações não equivale a requisito brasileiro nem critério automático de seleção para FPSO"
          ]
        },
        {
          "proposicao": "A mesma fonte afirma que, de acordo com SOLAS/FSS Code, determinados ambientes offshore a serem protegidos incluem camarotes, corredores, espaços públicos, salas de máquinas, sala de bombas e compartimentos de máquinas categoria A.",
          "trechos": [
            "Ec300a4f6074de672:698:1393",
            "Ec300a4f6074de672:1393:2082"
          ],
          "condicoes": [
            "Enquadramento apresentado pela própria fonte com remissão a norma estrangeira",
            "Aplicável aos ambientes listados no trecho"
          ],
          "limites": [
            "Não deve ser convertido automaticamente em requisito brasileiro",
            "O trecho não informa critérios de cobertura, agente, vazão ou arquitetura do sistema em cada ambiente"
          ]
        },
        {
          "proposicao": "A fonte reporta estudos segundo os quais sistemas fixos por agentes gasosos, em compartimentos de turbinas a gás, apresentaram elevada taxa de falhas atribuída em parte à perda do agente por ventilação ou portas abertas, sugerindo sensibilidade do desempenho à estanqueidade do ambiente.",
          "trechos": [
            "Ec300a4f6074de672:1393:2082"
          ],
          "condicoes": [
            "Resultado reportado para compartimentos de turbinas a gás",
            "Dependente das condições de ventilação e fechamento do ambiente"
          ],
          "limites": [
            "Os valores numéricos estão apagados e não podem ser reconstruídos",
            "Trata-se de relato de estudos citado por fonte secundária, não de regra universal para todos os sistemas gasosos"
          ]
        }
      ]
    },
    {
      "id": "E352fcd7265c3025c",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte relata dano significativo a estrutura de combate a incêndio e a tubulação no convés em eventos de embarque de água, indicando que condições ambientais extremas podem afetar fisicamente elementos envolvidos na resposta a emergência.",
          "trechos": [
            "E352fcd7265c3025c:0:694",
            "E352fcd7265c3025c:1393:2093"
          ],
          "condicoes": [
            "Aplicável a eventos de embarque de água em unidades offshore",
            "Dependente da localização de equipamentos e da severidade esperada do impacto de água"
          ],
          "limites": [
            "O trecho trata de integridade frente a ambiente marítimo, não de desempenho do combate a incêndio durante incêndio real",
            "Não traz critérios de projeto, inspeção ou aceitação para sistemas de incêndio"
          ]
        },
        {
          "proposicao": "A expectativa de ocorrência de embarque de água pode levar a alterações de projeto em equipamentos e estruturas do convés principal, incluindo barreiras físicas, reforços locais e proteções generalizadas para reduzir danos.",
          "trechos": [
            "E352fcd7265c3025c:0:694",
            "E352fcd7265c3025c:694:1393",
            "E352fcd7265c3025c:1393:2093"
          ],
          "condicoes": [
            "Aplicável quando a ocorrência de embarque de água é identificada em campo ou ensaios",
            "Dependente de arranjo da unidade e intensidade esperada do evento"
          ],
          "limites": [
            "Medidas apresentadas como exemplos de projeto, não como exigência universal",
            "O trecho não demonstra especificamente quais adaptações são necessárias para cada subsistema de combate a incêndio"
          ]
        }
      ]
    }
  ],
